    text = " ".join(words)
    if justify:
        if last or len(words) < 2:
            return text
        extra = space - len(text)
        gaps = len(words) - 1
        out = []
        for i, w in enumerate(words[:-1]):
            out.append(w + " " * (1 + extra // gaps + (1 if i < extra % gaps else 0)))
